import { FollowUp } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof FollowUp>, 'suggestions' | 'onSelect'> = {
    suggestions: [
      'Compare with last month',
      'Show only paid orders',
      { label: 'Export as a table', message: 'Export these orders as a table' },
    ],
    onSelect: () => {},
  };
  const [sent, setSent] = useState<string>();
  return (
    <div style={{ display: 'grid', gap: 'var(--space-3)', maxWidth: 520 }}>
      <FollowUp {...args} onSelect={setSent} />
      <p>Sent: {sent ?? 'nothing yet'}</p>
    </div>
  );
}

